const payload = $('Execute Workflow Trigger').item.json || {};
const chatId = String(payload.chatId || payload.message?.chat?.id || '').trim();
const content = String(payload.content || payload.memory_text || payload.summary || payload.rawText || payload.text || '').trim();
const memoryType = String(payload.memory_type || payload.memoryType || 'general').trim() || 'general';
const title = String(payload.title || '').trim();
const sourceText = String(payload.rawText || payload.text || content || '').trim();
const importance = Math.max(1, Math.min(5, Number(payload.importance || 3) || 3));
const tags = Array.isArray(payload.tags)
  ? payload.tags.map((tag) => String(tag || '').trim()).filter(Boolean)
  : String(payload.tags || '')
      .split(',')
      .map((tag) => tag.trim())
      .filter(Boolean);
const metadata = {
  memory_type: memoryType,
  tags,
  title,
  source: 'agent_tool',
  source_text: sourceText,
  importance,
};

const normalizeWhitespace = (value = '') => String(value || '').replace(/\s+/g, ' ').trim();
const normalizedContent = normalizeWhitespace(content);
const escapeSql = (value = '') => String(value || '').replace(/'/g, "''");
const normalize = (value = '') => String(value || '')
  .toLowerCase()
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .replace(/đ/g, 'd')
  .trim();
const hashHex = (input) => {
  let h1 = 0xdeadbeef ^ input.length;
  let h2 = 0x41c6ce57 ^ input.length;
  for (let index = 0; index < input.length; index += 1) {
    const codePoint = input.charCodeAt(index);
    h1 = Math.imul(h1 ^ codePoint, 2654435761);
    h2 = Math.imul(h2 ^ codePoint, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return `${(h2 >>> 0).toString(16).padStart(8, '0')}${(h1 >>> 0).toString(16).padStart(8, '0')}`;
};
const chunkText = (text, maxLength = 350, overlap = 60) => {
  const compact = normalizeWhitespace(text);
  if (!compact) return [];
  if (compact.length <= maxLength) return [compact];
  const segments = compact.split(/(?<=[.!?\n])\s+/).filter(Boolean);
  const chunks = [];
  let current = '';
  for (const segment of segments) {
    if (!current) {
      current = segment;
      continue;
    }
    if (`${current} ${segment}`.length <= maxLength) {
      current = `${current} ${segment}`;
      continue;
    }
    chunks.push(current);
    const carry = current.slice(Math.max(0, current.length - overlap)).trim();
    current = carry ? `${carry} ${segment}`.slice(0, maxLength) : segment;
  }
  if (current) chunks.push(current);
  const fixed = [];
  for (const chunk of chunks) {
    if (chunk.length <= maxLength) {
      fixed.push(chunk);
      continue;
    }
    for (let start = 0; start < chunk.length; start += maxLength - overlap) {
      fixed.push(chunk.slice(start, start + maxLength).trim());
    }
  }
  return fixed.filter(Boolean);
};

if (!chatId) {
  throw new Error('Missing chatId for memory_write');
}
if (!normalizedContent) {
  return [{
    json: {
      chatId,
      skip: true,
      responseText: 'MEMORY_WRITE_SKIPPED\nreason: empty content',
    },
  }];
}

const chunks = chunkText(normalizedContent);
const fingerprint = hashHex(`${chatId}|${normalize(memoryType)}|${normalize(normalizedContent)}`);
const tagsSql = `ARRAY[${tags.map((tag) => `'${escapeSql(tag)}'`).join(', ')}]::text[]`;
const metadataSql = `'${escapeSql(JSON.stringify(metadata))}'::jsonb`;
const itemUpsertSql = `INSERT INTO mia_memory_items (chat_id, fingerprint, memory_type, title, content, source_text, tags, importance, metadata, is_active, created_at, updated_at) VALUES ('${escapeSql(chatId)}', '${fingerprint}', '${escapeSql(memoryType)}', '${escapeSql(title)}', '${escapeSql(normalizedContent)}', '${escapeSql(sourceText)}', ${tags.length ? tagsSql : 'ARRAY[]::text[]'}, ${importance}, ${metadataSql}, true, now(), now()) ON CONFLICT (fingerprint) DO UPDATE SET memory_type = EXCLUDED.memory_type, title = EXCLUDED.title, content = EXCLUDED.content, source_text = EXCLUDED.source_text, tags = EXCLUDED.tags, importance = EXCLUDED.importance, metadata = EXCLUDED.metadata, is_active = true, updated_at = now() RETURNING id, chat_id, memory_type, title, tags, importance;`;

return [{
  json: {
    chatId,
    skip: false,
    content: normalizedContent,
    title,
    sourceText,
    memoryType,
    importance,
    tags,
    metadata,
    chunks,
    chunkCount: chunks.length,
    itemUpsertSql,
  },
}];

