const prepared = $('Prepare Memory Write').item.json || {};
if (prepared.skip) {
  return [{ json: { skip: true, responseText: prepared.responseText, chatId: prepared.chatId || '' } }];
}
const item = $('Upsert Memory Item').item.json || {};
const embedResponse = $('Embed Memory Chunks').item.json || {};
const embeddings = Array.isArray(embedResponse.embeddings) ? embedResponse.embeddings : [];
const chunks = Array.isArray(prepared.chunks) ? prepared.chunks : [];
if (!item.id) {
  throw new Error('Missing item id after memory item upsert');
}
if (embeddings.length !== chunks.length) {
  throw new Error(`Embedding count mismatch: expected ${chunks.length}, got ${embeddings.length}`);
}
const escapeSql = (value = '') => String(value || '').replace(/'/g, "''");
const vectorLiteral = (values) => `[${values.map((value) => Number(value).toFixed(8)).join(',')}]`;
const metadata = prepared.metadata || {};
const metadataSql = `'${escapeSql(JSON.stringify(metadata))}'::jsonb`;
const rows = chunks.map((chunk, index) => `(${Number(item.id)}, '${escapeSql(prepared.chatId)}', ${index}, '${escapeSql(chunk)}', '${vectorLiteral(embeddings[index] || [])}'::vector, ${metadataSql}, now())`);
const replaceSql = `DELETE FROM mia_memory_chunks WHERE item_id = ${Number(item.id)}; INSERT INTO mia_memory_chunks (item_id, chat_id, chunk_index, chunk_text, embedding, metadata, created_at) VALUES ${rows.join(', ')} RETURNING item_id;`;
return [{ json: { itemId: Number(item.id), chatId: prepared.chatId, chunkCount: chunks.length, replaceSql } }];

const prepared = $('Prepare Memory Write').item.json || {};
if (prepared.skip) {
  return [{ json: { text: prepared.responseText, chatId: prepared.chatId || '', result: null } }];
}
const item = $('Upsert Memory Item').item.json || {};
const chunkInfo = $('Build Chunk Replace SQL').item.json || {};
const tags = Array.isArray(item.tags) && item.tags.length ? `tags: ${item.tags.join(', ')}` : '';
const result = {
  id: item.id || null,
  chat_id: item.chat_id || prepared.chatId || '',
  memory_type: item.memory_type || prepared.memoryType || 'general',
  title: item.title || prepared.title || '',
  tags: Array.isArray(item.tags) ? item.tags : prepared.tags || [],
  importance: item.importance || prepared.importance || 3,
  chunk_count: chunkInfo.chunkCount || prepared.chunkCount || 0,
  content: prepared.content || ''
};
const lines = [
  'MEMORY_WRITE_OK',
  `memory_type: ${result.memory_type}`,
  `title: ${result.title || '(none)'}`,
  `chunks: ${result.chunk_count}`,
  `importance: ${result.importance}`,
  `content: ${result.content}`
];
if (tags) lines.push(tags);
return [{ json: { text: lines.join('\n'), chatId: result.chat_id, result } }];
